import os
import base64
import pathlib
import tempfile
import uuid
import mimetypes
import re
from typing import List, Optional, Tuple, Dict, Any

import anyio
import httpx
from fastapi import FastAPI, UploadFile, File, Form, Request
from fastapi.responses import HTMLResponse, Response, JSONResponse
from fastapi.middleware.gzip import GZipMiddleware

from flymyai import client, FlyMyAIPredictException

APP_DIR = pathlib.Path(__file__).resolve().parent
INDEX_PATH = APP_DIR / "index.html"

MODEL_NAME = "flymyai/nano-banana-pro"
ENV_API_KEY = "FLYMYAI_API_KEY"

MAX_FILES = 14
MAX_TOTAL_UPLOAD_BYTES = 200 * 1024 * 1024
ALLOWED_IMAGE_MIME = {
    "image/jpeg",
    "image/png",
    "image/webp",
    "image/avif",
    "image/heic",
    "image/heif",
    "image/gif",
    "image/tiff",
}

app = FastAPI()
app.add_middleware(GZipMiddleware, minimum_size=1024)


def _require_api_key() -> str:
    apikey = os.getenv(ENV_API_KEY, "").strip()
    if not apikey:
        raise RuntimeError(f"Missing {ENV_API_KEY} environment variable")
    return apikey


def _sanitize_text(s: Optional[str], max_len: int = 20000) -> Optional[str]:
    if s is None:
        return None
    s = s.strip()
    if not s:
        return None
    if len(s) > max_len:
        s = s[:max_len]
    return s


def _pick_output_from_response(
    output_ Dict[str, Any]
) -> Tuple[Optional[bytes], Optional[str], Optional[str], Dict[str, Any]]:
    meta: Dict[str, Any] = {"available_keys": list(output_data.keys())}

    for k in ["image", "sample", "images", "output", "result"]:
        if k in output_
            v = output_data.get(k)
            if isinstance(v, list) and v:
                first = v[0]
                if isinstance(first, str) and first.strip():
                    try:
                        b = base64.b64decode(first, validate=False)
                        meta["selected_key"] = k
                        meta["selected_type"] = "base64_list_first"
                        return b, None, None, meta
                    except Exception:
                        pass
                    if re.match(r"^https?://", first.strip(), re.IGNORECASE):
                        meta["selected_key"] = k
                        meta["selected_type"] = "url_list_first"
                        return None, first.strip(), None, meta
            if isinstance(v, str) and v.strip():
                s = v.strip()
                try:
                    b = base64.b64decode(s, validate=False)
                    meta["selected_key"] = k
                    meta["selected_type"] = "base64_str"
                    return b, None, None, meta
                except Exception:
                    pass
                if re.match(r"^https?://", s, re.IGNORECASE):
                    meta["selected_key"] = k
                    meta["selected_type"] = "url_str"
                    return None, s, None, meta

    for k in ["image_base64", "sample_base64", "output_base64"]:
        if k in output_
            v = output_data.get(k)
            if isinstance(v, str) and v.strip():
                try:
                    b = base64.b64decode(v.strip(), validate=False)
                    meta["selected_key"] = k
                    meta["selected_type"] = "base64_str"
                    return b, None, None, meta
                except Exception:
                    pass

    for k in ["image_url", "sample_url", "output_url", "url"]:
        if k in output_
            v = output_data.get(k)
            if isinstance(v, str) and v.strip() and re.match(
                    r"^https?://", v.strip(), re.IGNORECASE):
                meta["selected_key"] = k
                meta["selected_type"] = "url_str"
                return None, v.strip(), None, meta

    for k in ["mime_type", "content_type", "format"]:
        if k in output_data and isinstance(output_data.get(k), str):
            meta["hint_format_key"] = k
            meta["hint_format_value"] = output_data.get(k)

    return None, None, None, meta


async def _fetch_url_bytes(url: str) -> Tuple[bytes, str]:
    timeout = httpx.Timeout(60.0, connect=20.0)
    async with httpx.AsyncClient(timeout=timeout, follow_redirects=True) as hc:
        r = await hc.get(url)
        r.raise_for_status()
        ctype = r.headers.get(
            "content-type",
            "application/octet-stream").split(";")[0].strip().lower()
        return r.content, ctype or "application/octet-stream"


def _guess_content_type( bytes, preferred: Optional[str] = None) -> str:
    if preferred:
        p = preferred.strip().lower()
        if p.startswith("image/"):
            return p
        if p in {"jpg", "jpeg"}:
            return "image/jpeg"
        if p == "png":
            return "image/png"
        if p == "webp":
            return "image/webp"
        if p == "avif":
            return "image/avif"
        if p in {"heic", "heif"}:
            return "image/heic"
    if len(data) >= 12 and data[:8] == b"\x89PNG\r\n\x1a\n":
        return "image/png"
    if len(data) >= 3 and data[:3] == b"\xff\xd8\xff":
        return "image/jpeg"
    if len(data) >= 12 and data[:4] == b"RIFF" and data[8:12] == b"WEBP":
        return "image/webp"
    if len(data) >= 12 and data[:4] == b"\x00\x00\x00\x1c" and data[
            4:8] == b"ftyp":
        return "application/octet-stream"
    return "application/octet-stream"


async def _read_and_validate_files(
        files: List[UploadFile]) -> List[Tuple[str, pathlib.Path]]:
    if len(files) > MAX_FILES:
        raise ValueError(f"Too many images: {len(files)} (max {MAX_FILES})")
    total = 0
    saved: List[Tuple[str, pathlib.Path]] = []
    for i, f in enumerate(files):
        ct = (f.content_type or "").split(";")[0].strip().lower()
        if ct and ct not in ALLOWED_IMAGE_MIME:
            raise ValueError(f"Unsupported image type: {ct}")
        data = await f.read()
        if not 
            continue
        total += len(data)
        if total > MAX_TOTAL_UPLOAD_BYTES:
            raise ValueError("Total upload too large")
        suffix = ""
        name = (f.filename or "").strip()
        if name and "." in name:
            suffix = "." + name.rsplit(".", 1)[-1].lower()
        if not suffix and ct:
            ext = mimetypes.guess_extension(ct) or ""
            suffix = ext
        if not suffix:
            suffix = ".bin"
        tmp = tempfile.NamedTemporaryFile(delete=False, suffix=suffix)
        tmp.write(data)
        tmp.flush()
        tmp.close()
        key = "image" if i == 0 else f"image{i}"
        saved.append((key, pathlib.Path(tmp.name)))
    return saved


def _cleanup_paths(paths: List[pathlib.Path]) -> None:
    for p in paths:
        try:
            p.unlink(missing_ok=True)
        except Exception:
            pass


@app.get("/", response_class=HTMLResponse)
async def root() -> HTMLResponse:
    if not INDEX_PATH.exists():
        return HTMLResponse(
            "<!doctype html><html><body>Missing index.html</body></html>",
            status_code=500)
    return HTMLResponse(INDEX_PATH.read_text(encoding="utf-8"))


@app.post("/api/generate")
async def generate(
        request: Request,
        prompt: str = Form(...),
        aspect_ratio: Optional[str] = Form(None),
        image_size: Optional[str] = Form(None),
        output_format: Optional[str] = Form(None),
        files: List[UploadFile] = File(default=[]),
) -> Response:
    apikey = _require_api_key()

    prompt_s = _sanitize_text(prompt, max_len=20000)
    if not prompt_s:
        return JSONResponse({"error": "Missing prompt"}, status_code=400)

    aspect_ratio_s = _sanitize_text(aspect_ratio, max_len=64)
    image_size_s = _sanitize_text(image_size, max_len=64)
    output_format_s = _sanitize_text(output_format, max_len=16)

    saved = []
    tmp_paths: List[pathlib.Path] = []
    try:
        saved = await _read_and_validate_files(files)
        tmp_paths = [p for _, p in saved]

        payload: Dict[str, Any] = {
            "prompt": prompt_s,
            "aspect_ratio":
            aspect_ratio_s if aspect_ratio_s is not None else None,
            "image_size": image_size_s if image_size_s is not None else None,
        }

        if output_format_s:
            payload["output_format"] = output_format_s

        for key, path in saved:
            payload[key] = path

        fma_client = client(apikey=apikey)

        def _do_predict() -> Dict[str, Any]:
            resp = fma_client.predict(model=MODEL_NAME, payload=payload)
            od = getattr(resp, "output_data", None)
            if not isinstance(od, dict):
                raise RuntimeError(
                    "Invalid FlyMyAI response (missing output_data)")
            return od

        try:
            output_data = await anyio.to_thread.run_sync(_do_predict)
        except FlyMyAIPredictException as e:
            return JSONResponse(
                {
                    "error": "FlyMyAI prediction failed",
                    "code": getattr(e, "code", None),
                    "message": getattr(e, "message", str(e)),
                    "details": getattr(e, "details", None),
                },
                status_code=502,
            )
        except Exception as e:
            return JSONResponse(
                {
                    "error": "Prediction error",
                    "message": str(e)
                },
                status_code=502)

        img_bytes, url, _, meta = _pick_output_from_response(output_data)

        if img_bytes is None and url:
            try:
                img_bytes, ctype = await _fetch_url_bytes(url)
                ct = ctype
            except Exception as e:
                return JSONResponse(
                    {
                        "error": "Failed to fetch model output URL",
                        "message": str(e),
                        "url": url,
                        "meta": meta
                    },
                    status_code=502)
        elif img_bytes is not None:
            hint = None
            if isinstance(meta.get("hint_format_value"), str):
                hint = meta["hint_format_value"]
            if output_format_s:
                hint = output_format_s
            ct = _guess_content_type(img_bytes, preferred=hint)
        else:
            return JSONResponse(
                {
                    "error": "No image output found in response",
                    "meta": meta,
                    "output_keys": list(output_data.keys())
                },
                status_code=502)

        filename = f"nano-banana-pro-{uuid.uuid4().hex}"
        ext = mimetypes.guess_extension(ct) or ""
        if not ext and output_format_s:
            ext = "." + output_format_s.lower().lstrip(".")
        if not ext:
            ext = ".bin"
        filename += ext

        headers = {
            "Cache-Control": "no-store",
            "X-Model": MODEL_NAME,
            "X-Output-Content-Type": ct,
            "Content-Disposition": f'inline; filename="{filename}"',
        }

        return Response(content=img_bytes, media_type=ct, headers=headers)
    except ValueError as ve:
        return JSONResponse({
            "error": "Invalid input",
            "message": str(ve)
        },
                            status_code=400)
    finally:
        _cleanup_paths(tmp_paths)


@app.get("/healthz")
async def healthz() -> JSONResponse:
    ok = bool(os.getenv(ENV_API_KEY, "").strip())
    return JSONResponse({"ok": True, "has_api_key": ok, "model": MODEL_NAME})


if __name__ == "__main__":
    import uvicorn
    uvicorn.run("main:app",
                host=os.getenv("HOST", "0.0.0.0"),
                port=int(os.getenv("PORT", "5000")),
                log_level=os.getenv("LOG_LEVEL", "info"))


